<div class="page-title"><div><em>CUSTOMER MANAGEMENT</em><h1>Edit customer account</h1><p>Update identity, contact details, access status and login credentials.</p></div><div class="page-title-actions"><a class="outline" href="<?=site_url('admin/customers/'.$customer['id'])?>">Cancel</a><?=form_open('admin/customers/'.$customer['id'].'/login-as',array('class'=>'inline-form'))?><button class="btn" type="submit">↗ Login as customer</button></form></div></div>
<section class="panel form-panel narrow"><div class="panel-head"><div><h2>Account details</h2><p>Changes are recorded in the audit log.</p></div><span class="<?=status_class($customer['status'])?>"><?=ucfirst($customer['status'])?></span></div><?=form_open('admin/customers/'.$customer['id'].'/edit')?><div class="form-grid"><div><label>First name</label><input name="first_name" value="<?=html_escape($customer['first_name']??'')?>" required maxlength="80"></div><div><label>Last name</label><input name="last_name" value="<?=html_escape($customer['last_name']??'')?>" required maxlength="80"></div><div><label>Username</label><input name="username" value="<?=html_escape($customer['username']??'')?>" required maxlength="80" autocomplete="off"></div><div><label>Email address</label><input name="email" type="email" value="<?=html_escape($customer['email']??'')?>" required maxlength="190"></div><div><label>Phone number</label><input name="phone" value="<?=html_escape($customer['phone']??'')?>"></div><div><label>Country</label><input name="country" value="<?=html_escape($customer['country']??'')?>"></div><div><label>City</label><input name="city" value="<?=html_escape($customer['city']??'')?>"></div><div><label>Date of birth</label><input name="date_of_birth" type="date" value="<?=html_escape($customer['date_of_birth']??'')?>"></div></div><label>Home address</label><input name="address" value="<?=html_escape($customer['address']??'')?>"><label>Account status</label><select name="status"><option value="active" <?=$customer['status']==='active'?'selected':''?>>Active — customer can sign in</option><option value="pending" <?=$customer['status']==='pending'?'selected':''?>>Pending</option><option value="suspended" <?=$customer['status']==='suspended'?'selected':''?>>Suspended — customer cannot sign in</option><option value="closed" <?=$customer['status']==='closed'?'selected':''?>>Closed — customer cannot sign in</option></select><div class="admin-password-reset"><h3>Reset customer password</h3><p>Leave this blank to keep the current password. The customer will not be shown the new password automatically.</p><input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="Optional new password"></div><button class="btn">Save customer account</button></form></section>
